import { PumpToken } from '@/type/pump'
import { create, StateCreator } from 'zustand'

interface PumpTokenListState {
  //当前用户
  currAccount?: string

  // Created列表加载更多Loading
  createdTokenListLoading: boolean
  setCreatedTokenListLoading: (loading: boolean) => void

  // Created Token 列表
  createdTokenList: PumpToken[]
  setCreatedTokenList: (list: PumpToken[], currAccount?: string) => void

  maxPage: number
  setMaxPage: (page: number) => void
}

const store: StateCreator<PumpTokenListState> = (set, get) => ({
  maxPage: 1,
  currAccount: undefined,
  createdTokenListLoading: false,
  createdTokenList: [],
  setCreatedTokenListLoading: (loading: boolean) => {
    set(() => ({
      createdTokenListLoading: loading
    }))
  },
  setCreatedTokenList: (list: PumpToken[], currAccount?: string) => {
    set(() => ({
      currAccount,
      createdTokenList: list
    }))
  },
  setMaxPage: (page: number) => {
    set({
      maxPage: page
    })
  }
})

const useAccountCreateTokenListStore = create(store)
export default useAccountCreateTokenListStore
