import { AddressCopyLink } from '@cetus/design/src/components/common'
import Block from '@cetus/design/src/components/common/Block'
import useExplorer from '@cetus/hooks/src/useExplorer'
import { useAccountStore } from '@cetus/stores'
import { Button, HStack, Image, Text } from '@chakra-ui/react'
import { useDisconnectWallet } from '@mysten/dapp-kit'
import { useMemo } from 'react'
import { useParams } from 'react-router-dom'
import Diamond from '../../assets/images/img@2x.png'

export default function WalletBlock() {
  const { mutate: disconnect } = useDisconnectWallet()
  const { currentAccount } = useAccountStore()
  const { getExplorerUrl } = useExplorer()
  const { address } = useParams()

  const queryAddress = useMemo(() => {
    return address ? address : currentAccount?.address
  }, [currentAccount, address])

  return (
    <Block p={{ base: '28px 24px', lg: '20px 24px' }} h={{ base: 'unset', lg: '88px' }}>
      <HStack justifyContent="space-between" flexDirection={{ base: 'column', lg: 'row' }} gap={{ base: '32px', lg: '8px' }}>
        <HStack>
          <Image w="48px" h="48px" src={Diamond} borderRadius="50%" mr="8px" />
          {!queryAddress ? (
            <Text>--</Text>
          ) : (
            <AddressCopyLink
              address={queryAddress || ''}
              fontSize="20px"
              fontWeight="500"
              color="text_caption"
              onClickLink={() => {
                window.open(getExplorerUrl(queryAddress), '_blank')
              }}
              wrapStyle={{
                gap: '4px',
                sx: {
                  'div:first-of-type': {
                    ml: '8px'
                  }
                }
              }}
            />
          )}
        </HStack>
        {currentAccount && currentAccount?.address == queryAddress && (
          <Button
            onClick={() => {
              disconnect()
            }}
            borderRadius="8px"
            sx={{
              w: '160px',
              fontSize: '12px !important',
              fontWeight: '600 !important',
              svg: {
                w: '20px',
                h: '20px',
                mr: '8px'
              }
            }}
          >
            <svg aria-hidden="true">
              <use xlinkHref="#icon-icon_disconnect" />
            </svg>
            Disconnect
          </Button>
        )}
      </HStack>
    </Block>
  )
}
