import { BondingCurveStatus } from '@cetusprotocol/cetus-sui-pump-sdk'
import { Flex, Text } from '@chakra-ui/react'
import { useMemo } from 'react'

export default function TokensCreatedStatus({ status }: { status: BondingCurveStatus }) {
  const statusInfo = useMemo(() => {
    const statusInfo = {
      bg: 'primary_opacity.10',
      color: 'primary',
      text: 'Ongoing'
    }
    if (status === BondingCurveStatus.CREATED) {
      statusInfo.bg = 'primary_yellow_opacity.10'
      statusInfo.color = 'primary_yellow'
      statusInfo.text = 'Bonding curve pool not created'
    }
    if (status >= BondingCurveStatus.COMPLETED) {
      statusInfo.bg = 'primary_green_opacity.10'
      statusInfo.color = 'primary_green'
      statusInfo.text = 'Completed'
    }
    return statusInfo
  }, [status])

  return (
    <>
      <Flex w="98px" justifyContent="left">
        <Text lineHeight="24px" h="24px" fontSize="14px" color={statusInfo.color} bg={statusInfo.bg} borderRadius="8px" pl="16px" pr="16px">
          {statusInfo.text}
        </Text>
      </Flex>
    </>
  )
}
