import useAccountHeldTokenListStore from '@/store/accountHeldTokenList'
import { queryHolderCoinByCoinTypeList } from '@/type/api'
import { PumpUtils } from '@/utils/pumpUtils'
import { useInitSDK } from '@cetus/hooks/src/useInitSDK'
import { d, extractStructTagFromType, fromDecimalsAmount } from '@cetusprotocol/cetus-sui-clmm-sdk'
import { useEffect, useState } from 'react'
import { usePumpApiDomain } from '../common/usePumpApiDomain'
import { useGetClmmPoolList } from './useGetClmmPoolList'

export function useAccountHoldTokenList(account?: string) {
  const { heldTokenListLoading, setHeldTokenListLoading, currAccount, heldTokenList, setHeldTokenList } = useAccountHeldTokenListStore()
  const { fetchClmmData } = useGetClmmPoolList()

  const { pumpSdk } = useInitSDK()
  const [isLoadMoreError, setIsLoadMoreError] = useState<boolean>(false)
  const { fetchPostByApi } = usePumpApiDomain()

  const fetchAccountHoldTokenList = async (account: string) => {
    setIsLoadMoreError(false)
    setHeldTokenListLoading(true)
    const coinBalance = await pumpSdk.fullClient.getOwnerCoinBalances(account)
    const coinTypeList = coinBalance.filter(item => d(item.totalBalance).gt(0)).map(item => item.coinType)

    //  console.log('🚀 ~ file: useAccountHoldTokenList.ts:18 ~ fetchAccountHoldTokenList ~ coinTypeList:', coinTypeList)

    if (coinTypeList.length === 0) {
      setHeldTokenList([])
      setHeldTokenListLoading(false)
      return
    }

    const params = new URLSearchParams({ page: '1', page_size: '1000' })

    const api = `${queryHolderCoinByCoinTypeList}?${params.toString()}`

    try {
      const response = await fetchPostByApi(api, undefined, coinTypeList)

      const list: any[] = response.tokenVolumes

      if (list) {
        list.forEach((item: any) => {
          PumpUtils.formatPumpToken(item, undefined, false)
          const balance = coinBalance.find(coin => extractStructTagFromType(coin.coinType).full_address === item.coin_type)?.totalBalance || '0'
          item.owner_balance = balance
          item.owner_balance_ui = fromDecimalsAmount(balance, item.TokenDetail.decimals)
        })
        console.log('🚀 ~ file: useAccountHoldTokenList.ts:44 ~ list.forEach ~ list:', list)
        const result = list?.sort((a: any, b: any) => {
          const valueA = d(a.owner_balance_ui).mul(a.current_ui_price)
          const valueB = d(b.owner_balance_ui).mul(b.current_ui_price)
          if (valueA.eq(valueB)) {
            return d(b.current_ui_price).sub(a.current_ui_price).toNumber()
          }
          return valueB.sub(valueA).toNumber()
        }) // 升序
        setHeldTokenList(result, account)

        fetchClmmData(list)
      }

      console.log('🚀 ~ file: useAccountHoldTokenList.ts:37 ~ fetchAccountHoldTokenList ~ list:', list)
    } catch (error) {
      setHeldTokenList([])
      setIsLoadMoreError(true)
      console.log('🚀 ~ file: useAccountTokenList.ts:53 ~ fetchAccountTokenList ~ error:', error)
    } finally {
      setHeldTokenListLoading(false)
    }
  }

  useEffect(() => {
    if (account === undefined || currAccount === undefined || currAccount !== account) {
      setHeldTokenList([])
    }
  }, [account])

  return {
    fetchAccountHoldTokenList,
    heldTokenList,
    heldTokenListLoading,
    isLoadMoreError
  }
}
